package com.example.logistics.warehouse.application;

import com.example.logistics.shared.api.ApiException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

/** Transactional warehouse workflows. Stock changes and their ledger rows commit together. */
@Service
public class WarehouseService {
    private final JdbcTemplate db; private final ObjectMapper json;
    public WarehouseService(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}

    @Transactional(readOnly=true) public Map<String,Object> dashboard(UUID org){
        return Map.of("skuCount",count("SELECT COUNT(DISTINCT product_id) FROM inventory_item WHERE organization_id=?",org),
                "onHand",decimal("SELECT COALESCE(SUM(qty_on_hand),0) FROM inventory_item WHERE organization_id=?",org),
                "reserved",decimal("SELECT COALESCE(SUM(qty_reserved),0) FROM inventory_item WHERE organization_id=?",org),
                "openReceipts",count("SELECT COUNT(*) FROM goods_receipt WHERE organization_id=? AND status IN ('RECEIVING','QC_PENDING')",org),
                "openPutaway",count("SELECT COUNT(*) FROM putaway_task WHERE organization_id=? AND status='OPEN'",org),
                "openPicks",count("SELECT COUNT(*) FROM pick_list WHERE organization_id=? AND status IN ('OPEN','PICKING')",org),
                "openCounts",count("SELECT COUNT(*) FROM stock_count WHERE organization_id=? AND status IN ('OPEN','COUNTING','PENDING_APPROVAL')",org));
    }
    @Transactional(readOnly=true) public List<Map<String,Object>> locations(UUID org){return db.queryForList("SELECT id,warehouse_id warehouseId,parent_id parentId,code,name,location_type locationType,zone,capacity,occupied,active FROM warehouse_location WHERE organization_id=? ORDER BY code",org.toString());}
    @Transactional(readOnly=true) public List<Map<String,Object>> receipts(UUID org){return db.queryForList("SELECT gr.id receiptId,gr.receipt_number receiptNumber,gr.status receiptStatus,gl.id lineId,gl.product_id productId,gl.quantity,gl.quality_status qualityStatus,gl.lot_code lotCode,gl.serial_number serialNumber,gl.expires_at expiresAt,gl.suggested_location_id suggestedLocationId FROM goods_receipt gr JOIN goods_receipt_line gl ON gl.receipt_id=gr.id WHERE gr.organization_id=? ORDER BY gr.received_at DESC",org.toString());}
    @Transactional(readOnly=true) public List<Map<String,Object>> putaways(UUID org){return db.queryForList("SELECT p.id taskId,p.receipt_line_id receiptLineId,p.inventory_item_id inventoryItemId,p.target_location_id targetLocationId,l.code targetCode,p.quantity,p.status FROM putaway_task p JOIN warehouse_location l ON l.id=p.target_location_id WHERE p.organization_id=? AND p.status='OPEN' ORDER BY p.created_at",org.toString());}
    @Transactional(readOnly=true) public List<Map<String,Object>> picks(UUID org){return db.queryForList("SELECT pl.id lineId,p.id pickListId,p.order_id orderId,pl.order_line_id orderLineId,pl.inventory_item_id inventoryItemId,pl.requested_qty requestedQty,pl.picked_qty pickedQty,pl.status,i.product_id productId,l.code locationCode FROM pick_list_line pl JOIN pick_list p ON p.id=pl.pick_list_id JOIN inventory_item i ON i.id=pl.inventory_item_id JOIN warehouse_location l ON l.id=i.location_id WHERE p.organization_id=? ORDER BY p.created_at DESC",org.toString());}
    @Transactional(readOnly=true) public List<Map<String,Object>> countLines(UUID org){return db.queryForList("SELECT c.id countId,c.count_number countNumber,c.status countStatus,c.count_type countType,cl.id lineId,cl.inventory_item_id inventoryItemId,IF(c.blind,NULL,cl.expected_qty) expectedQty,cl.counted_qty countedQty FROM stock_count c JOIN stock_count_line cl ON cl.count_id=c.id WHERE c.organization_id=? AND c.status<>'APPROVED' ORDER BY c.created_at DESC",org.toString());}
    @Transactional public Map<String,Object> createLocation(UUID org,Map<String,Object>b){
        String code=required(b,"code"),name=required(b,"name"); UUID id=UUID.randomUUID(); UUID parent=uuid(b.get("parentId"));
        db.update("INSERT INTO warehouse_location(id,organization_id,warehouse_id,parent_id,code,name,location_type,zone,capacity) VALUES(?,?,?,?,?,?,?,?,?)",id.toString(),org.toString(),str(b.get("warehouseId")),parent==null?null:parent.toString(),code,name,norm(b.get("locationType"),"BIN"),str(b.get("zone")),b.get("capacity"));
        return db.queryForMap("SELECT id,code,name,location_type locationType,zone,capacity,occupied FROM warehouse_location WHERE id=?",id.toString());
    }
    @Transactional(readOnly=true) public List<Map<String,Object>> inventory(UUID org,String search){String q="%"+(search==null?"":search.trim())+"%";return db.queryForList("SELECT i.id,i.product_id productId,p.name productName,i.location_id locationId,l.code locationCode,i.lot_code lotCode,i.serial_number serialNumber,i.expires_at expiresAt,i.qty_on_hand qtyOnHand,i.qty_reserved qtyReserved,(i.qty_on_hand-i.qty_reserved) available FROM inventory_item i JOIN warehouse_location l ON l.id=i.location_id LEFT JOIN master_data_record p ON p.id=i.product_id AND p.organization_id=i.organization_id AND p.resource_type='products' WHERE i.organization_id=? AND (p.name LIKE ? OR p.code LIKE ? OR i.lot_code LIKE ? OR l.code LIKE ?) ORDER BY p.name,i.expires_at",org.toString(),q,q,q,q);}
    @Transactional(readOnly=true) public List<Map<String,Object>> movements(UUID org){return db.queryForList("SELECT m.id,m.movement_type movementType,m.quantity,m.reference_type referenceType,m.reference_id referenceId,m.reverses_movement_id reversesMovementId,m.actor_id actorId,m.occurred_at occurredAt,i.product_id productId,i.location_id locationId,i.lot_code lotCode FROM stock_movement m JOIN inventory_item i ON i.id=m.inventory_item_id WHERE m.organization_id=? ORDER BY m.occurred_at DESC LIMIT 500",org.toString());}
    @Transactional(readOnly=true) public List<Map<String,Object>> suggest(UUID org,UUID product,BigDecimal qty){return db.queryForList("SELECT id,code,name,zone,capacity,occupied,(capacity-occupied) remainingCapacity FROM warehouse_location WHERE organization_id=? AND active=TRUE AND location_type='BIN' AND (capacity IS NULL OR capacity-occupied>=?) AND (zone IS NULL OR EXISTS(SELECT 1 FROM master_data_record p WHERE p.id=? AND JSON_SEARCH(p.attributes_json,'one',warehouse_location.zone,'$.compatibleZones') IS NOT NULL)) ORDER BY occupied ASC,code LIMIT 20",org.toString(),qty,product.toString());}

    @Transactional public Map<String,Object> receive(UUID org,UUID actor,Map<String,Object>b){
        List<Map<String,Object>> lines=maps(b.get("lines")); if(lines.isEmpty())throw bad("Receipt requires at least one line");
        UUID id=UUID.randomUUID(); String number=next(org,"GR"); UUID po=uuid(b.get("purchaseOrderId")),asn=uuid(b.get("asnId"));
        db.update("INSERT INTO goods_receipt(id,organization_id,receipt_number,purchase_order_id,asn_id,status,received_by) VALUES(?,?,?,?,?,'QC_PENDING',?)",id.toString(),org.toString(),number,po==null?null:po.toString(),asn==null?null:asn.toString(),actor==null?null:actor.toString());
        for(Map<String,Object> line:lines){BigDecimal qty=amount(line,"quantity"); UUID product=requiredUuid(line,"productId"); UUID loc=suggest(org,product,qty).stream().findFirst().map(x->UUID.fromString(x.get("id").toString())).orElse(null); if(loc==null)loc=defaultLocation(org);
            db.update("INSERT INTO goods_receipt_line(id,receipt_id,product_id,quantity,quality_status,lot_code,serial_number,expires_at,suggested_location_id) VALUES(?,?,?,?,'PENDING',?,?,?,?)",UUID.randomUUID().toString(),id.toString(),product.toString(),qty,line.get("lotCode"),line.get("serialNumber"),date(line.get("expiresAt")),loc==null?null:loc.toString()); }
        return db.queryForMap("SELECT id,receipt_number receiptNumber,status,received_at receivedAt FROM goods_receipt WHERE id=?",id.toString());
    }
    @Transactional public Map<String,Object> quality(UUID org,UUID actor,UUID receipt,UUID line,String decision){
        var r=receiptLine(org,receipt,line); String result=decision.toUpperCase(Locale.ROOT); if(!Set.of("ACCEPTED","REJECTED","QUARANTINED").contains(result))throw bad("Quality status must be ACCEPTED, REJECTED, or QUARANTINED");
        db.update("UPDATE goods_receipt_line SET quality_status=? WHERE id=?",result,line.toString());
        if(result.equals("ACCEPTED")){UUID item=stock(org,r.get("product_id").toString(),r.get("suggested_location_id")==null?defaultLocation(org).toString():r.get("suggested_location_id").toString(),r.get("lot_code"),r.get("serial_number"),r.get("expires_at")); BigDecimal qty=(BigDecimal)r.get("quantity"); db.update("UPDATE inventory_item SET qty_on_hand=qty_on_hand+?,version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",qty,item.toString()); movement(org,item,"RECEIPT",qty,null,(String)r.get("suggested_location_id"),"GOODS_RECEIPT",receipt,actor,null); db.update("UPDATE warehouse_location SET occupied=occupied+? WHERE id=?",qty,r.get("suggested_location_id"));
            db.update("INSERT INTO putaway_task(id,organization_id,receipt_line_id,inventory_item_id,source_location_id,target_location_id,quantity,status) VALUES(?,?,?,?,?,?,?,'OPEN')",UUID.randomUUID().toString(),org.toString(),line.toString(),item.toString(),r.get("suggested_location_id"),r.get("suggested_location_id"),qty);
        }
        int pending=db.queryForObject("SELECT COUNT(*) FROM goods_receipt_line WHERE receipt_id=? AND quality_status='PENDING'",Integer.class,receipt.toString()); if(pending==0)db.update("UPDATE goods_receipt SET status='RECEIVED' WHERE id=?",receipt.toString()); return Map.of("lineId",line,"qualityStatus",result);
    }
    @Transactional public Map<String,Object> completePutaway(UUID org,UUID actor,UUID task,UUID target){
        var t=db.query("SELECT p.*,i.location_id current_location FROM putaway_task p JOIN inventory_item i ON i.id=p.inventory_item_id WHERE p.id=? AND p.organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,task.toString(),org.toString()); if(t==null)throw missing("PUTAWAY_TASK_NOT_FOUND"); if(!"OPEN".equals(t.get("status")))throw conflict("Putaway task is not open");
        var bin=db.query("SELECT * FROM warehouse_location WHERE id=? AND organization_id=? AND active=TRUE FOR UPDATE",rs->rs.next()?row(rs):null,target.toString(),org.toString()); if(bin==null)throw bad("Target bin is unavailable"); BigDecimal qty=(BigDecimal)t.get("quantity"),capacity=(BigDecimal)bin.get("capacity"),occupied=(BigDecimal)bin.get("occupied"); if(capacity!=null&&capacity.subtract(occupied).compareTo(qty)<0)throw conflict("Target bin capacity exceeded");
        UUID item=UUID.fromString(t.get("inventory_item_id").toString()); String from=t.get("current_location").toString(); db.update("UPDATE inventory_item SET location_id=?,version=version+1 WHERE id=?",target.toString(),item.toString()); db.update("UPDATE warehouse_location SET occupied=GREATEST(0,occupied-?) WHERE id=?",qty,from); db.update("UPDATE warehouse_location SET occupied=occupied+? WHERE id=?",qty,target.toString()); movement(org,item,"PUTAWAY",qty,from,target.toString(),"PUTAWAY_TASK",task,actor,null); db.update("UPDATE putaway_task SET target_location_id=?,status='DONE',assigned_to=?,completed_at=CURRENT_TIMESTAMP(6) WHERE id=?",target.toString(),actor==null?null:actor.toString(),task.toString()); return Map.of("taskId",task,"status","DONE");
    }

    @Transactional public Map<String,Object> allocate(UUID org,UUID actor,UUID order,String strategy){
        strategy=norm(strategy,"FEFO"); if(!Set.of("FEFO","FIFO").contains(strategy))throw bad("Allocation strategy must be FEFO or FIFO");
        if(db.queryForList("SELECT id FROM sales_order WHERE id=? AND organization_id=? FOR UPDATE",String.class,order.toString(),org.toString()).isEmpty())throw missing("ORDER_NOT_FOUND");
        if(db.queryForObject("SELECT COUNT(*) FROM pick_list WHERE organization_id=? AND order_id=?",Integer.class,org.toString(),order.toString())>0)throw conflict("Order already has a pick list; release reservations before reallocating");
        List<Map<String,Object>> lines=db.queryForList("SELECT l.id,l.product_id,l.quantity FROM order_line l JOIN sales_order o ON o.id=l.order_id WHERE o.id=? AND o.organization_id=?",order.toString(),org.toString()); if(lines.isEmpty())throw bad("Order has no lines"); UUID pick=UUID.randomUUID(); db.update("INSERT INTO pick_list(id,organization_id,order_id,status) VALUES(?,?,?,'OPEN')",pick.toString(),org.toString(),order.toString());
        for(var line:lines){BigDecimal required=(BigDecimal)line.get("quantity"),remaining=required; String ordering=strategy.equals("FEFO")?"expires_at IS NULL,expires_at,created_at":"created_at";
            List<Map<String,Object>> items=db.queryForList("SELECT * FROM inventory_item WHERE organization_id=? AND product_id=? AND qty_on_hand>qty_reserved AND (expires_at IS NULL OR expires_at>=CURRENT_DATE) ORDER BY "+ordering+" FOR UPDATE",org.toString(),line.get("product_id"));
            for(var item:items){if(remaining.signum()==0)break; BigDecimal available=((BigDecimal)item.get("qty_on_hand")).subtract((BigDecimal)item.get("qty_reserved")); BigDecimal reserved=available.min(remaining); if(reserved.signum()<=0)continue;
                db.update("UPDATE inventory_item SET qty_reserved=qty_reserved+?,version=version+1 WHERE id=? AND qty_on_hand-qty_reserved>=?",reserved,item.get("id"),reserved); db.update("INSERT INTO inventory_reservation(id,organization_id,order_id,order_line_id,inventory_item_id,quantity,status,expires_at) VALUES(?,?,?,?,?,?,'ACTIVE',DATE_ADD(CURRENT_TIMESTAMP(6),INTERVAL 24 HOUR))",UUID.randomUUID().toString(),org.toString(),order.toString(),line.get("id"),item.get("id"),reserved);
                db.update("INSERT INTO pick_list_line(id,pick_list_id,order_line_id,inventory_item_id,requested_qty,picked_qty,status) VALUES(?,?,?,?,?,0,'OPEN')",UUID.randomUUID().toString(),pick.toString(),line.get("id"),item.get("id"),reserved); remaining=remaining.subtract(reserved);
            }
        }
        return Map.of("pickListId",pick,"status","OPEN","lines",db.queryForList("SELECT id,order_line_id orderLineId,inventory_item_id inventoryItemId,requested_qty requestedQty FROM pick_list_line WHERE pick_list_id=?",pick.toString()),"backordered",db.queryForList("SELECT ol.id orderLineId,ol.product_id productId,ol.quantity-COALESCE(SUM(pl.requested_qty),0) quantity FROM order_line ol LEFT JOIN pick_list_line pl ON pl.order_line_id=ol.id AND pl.pick_list_id=? WHERE ol.order_id=? GROUP BY ol.id,ol.product_id,ol.quantity HAVING quantity>0",pick.toString(),order.toString()));
    }
    @Transactional public Map<String,Object> pick(UUID org,UUID actor,UUID line,BigDecimal qty,String barcode){
        var row=db.query("SELECT pl.*,i.organization_id,i.product_id,i.location_id,i.qty_on_hand,i.qty_reserved FROM pick_list_line pl JOIN inventory_item i ON i.id=pl.inventory_item_id JOIN pick_list p ON p.id=pl.pick_list_id WHERE pl.id=? AND p.organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,line.toString(),org.toString()); if(row==null)throw missing("PICK_LINE_NOT_FOUND"); if(barcode!=null&&!barcode.isBlank()&&!barcode.equals(row.get("inventory_item_id").toString())&&!barcode.equals(row.get("product_id").toString()))throw bad("Scanned barcode does not match the allocated product"); BigDecimal requested=(BigDecimal)row.get("requested_qty"),picked=(BigDecimal)row.get("picked_qty"); if(qty.signum()<=0||picked.add(qty).compareTo(requested)>0)throw bad("Pick quantity exceeds allocated quantity"); if(((BigDecimal)row.get("qty_on_hand")).compareTo(qty)<0)throw conflict("Insufficient stock");
        db.update("UPDATE inventory_item SET qty_on_hand=qty_on_hand-?,qty_reserved=GREATEST(0,qty_reserved-?),version=version+1 WHERE id=? AND qty_on_hand>=? AND qty_reserved>=?",qty,qty,row.get("inventory_item_id"),qty,qty); int reservationChanged=db.update("UPDATE inventory_reservation SET quantity=quantity-?,status=IF(quantity-?<=0,'CONSUMED','ACTIVE') WHERE inventory_item_id=? AND order_line_id=(SELECT order_line_id FROM pick_list_line WHERE id=?) AND status='ACTIVE' AND quantity>=?",qty,qty,row.get("inventory_item_id"),line.toString(),qty); if(reservationChanged==0)throw conflict("Active reservation not found for this pick"); db.update("UPDATE pick_list_line SET picked_qty=picked_qty+?,status=IF(picked_qty+?>=requested_qty,'PICKED','PICKING') WHERE id=?",qty,qty,line.toString()); UUID item=UUID.fromString(row.get("inventory_item_id").toString()); movement(org,item,"PICK",qty,row.get("location_id").toString(),null,"PICK_LINE",line,actor,null); if(db.queryForObject("SELECT COUNT(*) FROM pick_list_line WHERE pick_list_id=(SELECT pick_list_id FROM pick_list_line WHERE id=?) AND status NOT IN ('PICKED','SHORT')",Integer.class,line.toString())==0)db.update("UPDATE pick_list SET status='PICKED' WHERE id=(SELECT pick_list_id FROM pick_list_line WHERE id=?)",line.toString()); return Map.of("lineId",line,"pickedQty",picked.add(qty),"status",picked.add(qty).compareTo(requested)>=0?"PICKED":"PARTIAL");
    }
    @Transactional public Map<String,Object> shortPick(UUID org,UUID line){var row=db.query("SELECT pl.*,i.id stock_id FROM pick_list_line pl JOIN pick_list p ON p.id=pl.pick_list_id JOIN inventory_item i ON i.id=pl.inventory_item_id WHERE pl.id=? AND p.organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,line.toString(),org.toString());if(row==null)throw missing("PICK_LINE_NOT_FOUND");if(Set.of("PICKED","SHORT").contains(row.get("status").toString()))throw conflict("Pick line is already complete");BigDecimal remaining=((BigDecimal)row.get("requested_qty")).subtract((BigDecimal)row.get("picked_qty"));if(remaining.signum()>0){db.update("UPDATE inventory_item SET qty_reserved=GREATEST(0,qty_reserved-?),version=version+1 WHERE id=?",remaining,row.get("inventory_item_id"));db.update("UPDATE inventory_reservation SET quantity=quantity-?,status=IF(quantity-?<=0,'RELEASED','ACTIVE') WHERE inventory_item_id=? AND order_line_id=? AND status='ACTIVE' AND quantity>=?",remaining,remaining,row.get("inventory_item_id"),row.get("order_line_id"),remaining);}db.update("UPDATE pick_list_line SET requested_qty=picked_qty,status='SHORT' WHERE id=?",line.toString());if(db.queryForObject("SELECT COUNT(*) FROM pick_list_line WHERE pick_list_id=(SELECT pick_list_id FROM pick_list_line WHERE id=?) AND status NOT IN ('PICKED','SHORT')",Integer.class,line.toString())==0)db.update("UPDATE pick_list SET status='PICKED' WHERE id=(SELECT pick_list_id FROM pick_list_line WHERE id=?)",line.toString());return Map.of("lineId",line,"status","SHORT","backorderQty",remaining);}
    @Transactional public Map<String,Object> release(UUID org,UUID order){List<Map<String,Object>> rs=db.queryForList("SELECT * FROM inventory_reservation WHERE organization_id=? AND order_id=? AND status='ACTIVE' FOR UPDATE",org.toString(),order.toString()); for(var r:rs){db.update("UPDATE inventory_item SET qty_reserved=GREATEST(0,qty_reserved-?),version=version+1 WHERE id=?",r.get("quantity"),r.get("inventory_item_id"));db.update("UPDATE inventory_reservation SET status='RELEASED' WHERE id=?",r.get("id"));}return Map.of("released",rs.size());}
    @Transactional public Map<String,Object> pack(UUID org,UUID order,String packageCode,BigDecimal weight){if(db.queryForObject("SELECT COUNT(*) FROM pick_list WHERE organization_id=? AND order_id=? AND status NOT IN ('PICKED','PACKED')",Integer.class,org.toString(),order.toString())>0)throw conflict("All pick lines must be completed before packing");UUID id=UUID.randomUUID();db.update("INSERT INTO package(id,organization_id,order_id,package_code,weight,status) VALUES(?,?,?,?,?,'PACKED')",id.toString(),org.toString(),order.toString(),packageCode,weight);db.update("UPDATE pick_list SET status='PACKED' WHERE organization_id=? AND order_id=?",org.toString(),order.toString());return Map.of("packageId",id,"packageCode",packageCode,"status","PACKED");}
    @Transactional public Map<String,Object> createCount(UUID org,UUID actor,String type,boolean blind){String key=norm(type,"CYCLE");if(!Set.of("CYCLE","ABC","RANDOM","FULL").contains(key))throw bad("Unsupported stock count type");UUID id=UUID.randomUUID();db.update("INSERT INTO stock_count(id,organization_id,count_number,count_type,status,blind,created_by) VALUES(?,?,?,?,'COUNTING',?,?)",id.toString(),org.toString(),next(org,"CNT"),key,blind,actor==null?null:actor.toString());db.update("INSERT INTO stock_count_line(id,count_id,inventory_item_id,expected_qty) SELECT UUID(),?,id,qty_on_hand FROM inventory_item WHERE organization_id=?"+(key.equals("RANDOM")?" ORDER BY RAND() LIMIT 25":""),id.toString(),org.toString());return Map.of("countId",id,"status","COUNTING","lines",db.queryForList("SELECT id,inventory_item_id inventoryItemId,"+(blind?"NULL":"expected_qty")+" expectedQty FROM stock_count_line WHERE count_id=?",id.toString()));}
    @Transactional public Map<String,Object> countLine(UUID org,UUID line,BigDecimal counted){var row=db.query("SELECT cl.*,c.status,c.organization_id FROM stock_count_line cl JOIN stock_count c ON c.id=cl.count_id WHERE cl.id=? AND c.organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,line.toString(),org.toString());if(row==null)throw missing("COUNT_LINE_NOT_FOUND");if(!"COUNTING".equals(row.get("status")))throw conflict("Count is not open");db.update("UPDATE stock_count_line SET counted_qty=?,counted_at=CURRENT_TIMESTAMP(6) WHERE id=?",counted,line.toString());int open=db.queryForObject("SELECT COUNT(*) FROM stock_count_line WHERE count_id=(SELECT count_id FROM stock_count_line WHERE id=?) AND counted_qty IS NULL",Integer.class,line.toString());if(open==0)db.update("UPDATE stock_count SET status='PENDING_APPROVAL' WHERE id=(SELECT count_id FROM stock_count_line WHERE id=?)",line.toString());return Map.of("lineId",line,"countedQty",counted,"remainingLines",open);}
    @Transactional public Map<String,Object> approveCount(UUID org,UUID actor,UUID count){var c=db.query("SELECT * FROM stock_count WHERE id=? AND organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,count.toString(),org.toString());if(c==null)throw missing("STOCK_COUNT_NOT_FOUND");if(!"PENDING_APPROVAL".equals(c.get("status")))throw conflict("Count is not awaiting approval");List<Map<String,Object>> lines=db.queryForList("SELECT cl.*,i.qty_reserved FROM stock_count_line cl JOIN inventory_item i ON i.id=cl.inventory_item_id WHERE cl.count_id=? AND cl.counted_qty<>cl.expected_qty",count.toString());for(var l:lines){BigDecimal actual=(BigDecimal)l.get("counted_qty"),reserved=(BigDecimal)l.get("qty_reserved"),delta=actual.subtract((BigDecimal)l.get("expected_qty"));if(actual.compareTo(reserved)<0)throw conflict("Counted stock is below active reservations");UUID item=UUID.fromString(l.get("inventory_item_id").toString());db.update("UPDATE inventory_item SET qty_on_hand=?,version=version+1 WHERE id=?",actual,item.toString());movement(org,item,"COUNT_ADJUST",delta.abs(),null,null,"STOCK_COUNT",count,actor,null);}db.update("UPDATE stock_count SET status='APPROVED',approved_by=? WHERE id=?",actor==null?null:actor.toString(),count.toString());return Map.of("countId",count,"status","APPROVED","adjustments",lines.size());}
    @Transactional public Map<String,Object> reverseMovement(UUID org,UUID actor,UUID movementId){var m=db.query("SELECT * FROM stock_movement WHERE id=? AND organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,movementId.toString(),org.toString());if(m==null)throw missing("MOVEMENT_NOT_FOUND");if(db.queryForObject("SELECT COUNT(*) FROM stock_movement WHERE reverses_movement_id=?",Integer.class,movementId.toString())>0)throw conflict("Movement already reversed");UUID item=UUID.fromString(m.get("inventory_item_id").toString());BigDecimal qty=(BigDecimal)m.get("quantity"),delta=((BigDecimal)m.get("quantity_delta")).negate();if(delta.signum()<0){int changed=db.update("UPDATE inventory_item SET qty_on_hand=qty_on_hand+?,version=version+1 WHERE id=? AND qty_on_hand+?>=qty_reserved",delta,item.toString(),delta);if(changed==0)throw conflict("Reversal would consume reserved stock");}else if(delta.signum()>0)db.update("UPDATE inventory_item SET qty_on_hand=qty_on_hand+?,version=version+1 WHERE id=?",delta,item.toString());return Map.of("reversalMovementId",movement(org,item,"ADJUSTMENT",qty,m.get("to_location_id")==null?null:m.get("to_location_id").toString(),m.get("from_location_id")==null?null:m.get("from_location_id").toString(),"REVERSAL",movementId,actor,movementId.toString()),"reversesMovementId",movementId);}

    private Map<String,Object> receiptLine(UUID org,UUID receipt,UUID line){var m=db.query("SELECT gl.*,gr.status receipt_status FROM goods_receipt_line gl JOIN goods_receipt gr ON gr.id=gl.receipt_id WHERE gl.id=? AND gl.receipt_id=? AND gr.organization_id=? FOR UPDATE",rs->rs.next()?row(rs):null,line.toString(),receipt.toString(),org.toString());if(m==null)throw missing("RECEIPT_LINE_NOT_FOUND");if(!"PENDING".equals(m.get("quality_status")))throw conflict("Quality decision already recorded");return m;}
    private UUID stock(UUID org,String product,String loc,Object lot,Object serial,Object expiry){List<Map<String,Object>> found=db.queryForList("SELECT id FROM inventory_item WHERE organization_id=? AND product_id=? AND location_id=? AND lot_code <=> ? AND serial_number <=> ? AND expires_at <=> ? FOR UPDATE",org.toString(),product,loc,lot,serial,expiry);if(!found.isEmpty())return UUID.fromString(found.get(0).get("id").toString());UUID id=UUID.randomUUID();db.update("INSERT INTO inventory_item(id,organization_id,product_id,location_id,lot_code,serial_number,expires_at) VALUES(?,?,?,?,?,?,?)",id.toString(),org.toString(),product,loc,lot,serial,expiry);return id;}
    private UUID defaultLocation(UUID org){List<Map<String,Object>> r=db.queryForList("SELECT id FROM warehouse_location WHERE organization_id=? AND active=TRUE ORDER BY location_type='RECEIVING' DESC,code LIMIT 1",org.toString());if(r.isEmpty())throw bad("Create at least one active warehouse location before receiving stock");return UUID.fromString(r.get(0).get("id").toString());}
    private UUID movement(UUID org,UUID item,String type,BigDecimal qty,String from,String to,String ref,UUID refId,UUID actor,String reverses){BigDecimal delta=BigDecimal.ZERO; if(reverses!=null){BigDecimal original=db.queryForObject("SELECT quantity_delta FROM stock_movement WHERE id=?",BigDecimal.class,reverses);delta=original.negate();}else if(type.equals("RECEIPT")||type.equals("RETURN"))delta=qty;else if(type.equals("PICK")||type.equals("SHIP"))delta=qty.negate();else if(type.equals("COUNT_ADJUST")){BigDecimal difference=db.queryForObject("SELECT counted_qty-expected_qty FROM stock_count_line WHERE count_id=? AND inventory_item_id=?",BigDecimal.class,refId.toString(),item.toString());delta=difference;}UUID id=UUID.randomUUID();db.update("INSERT INTO stock_movement(id,organization_id,inventory_item_id,movement_type,quantity,quantity_delta,from_location_id,to_location_id,reference_type,reference_id,reverses_movement_id,actor_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id.toString(),org.toString(),item.toString(),type,qty,delta,from,to,ref,refId==null?null:refId.toString(),reverses,actor==null?null:actor.toString());return id;}
    private String next(UUID org,String key){db.update("INSERT INTO number_sequence(id,scope_id,sequence_key,prefix,current_value) VALUES(?,?,?,?,0) ON DUPLICATE KEY UPDATE sequence_key=VALUES(sequence_key)",UUID.randomUUID().toString(),org.toString(),key,key+"-",0);db.update("UPDATE number_sequence SET current_value=LAST_INSERT_ID(current_value+1) WHERE scope_id=? AND sequence_key=?",org.toString(),key);return key+"-"+String.format("%08d",db.queryForObject("SELECT LAST_INSERT_ID()",Long.class));}
    private int count(String sql,UUID org){return db.queryForObject(sql,Integer.class,org.toString());}private BigDecimal decimal(String sql,UUID org){return db.queryForObject(sql,BigDecimal.class,org.toString());}
    private List<Map<String,Object>> maps(Object v){if(v instanceof List<?> l)return l.stream().filter(Map.class::isInstance).map(x->(Map<String,Object>)x).toList();return List.of();}
    private Map<String,Object> row(java.sql.ResultSet rs)throws java.sql.SQLException{var m=new LinkedHashMap<String,Object>();var md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),rs.getObject(i));return m;}
    private String required(Map<String,Object>b,String k){String s=str(b.get(k));if(s==null||s.isBlank())throw bad(k+" is required");return s.trim();}private UUID requiredUuid(Map<String,Object>b,String k){try{return UUID.fromString(required(b,k));}catch(Exception e){throw bad(k+" must be a UUID");}}private UUID uuid(Object v){try{return v==null?null:UUID.fromString(v.toString());}catch(Exception e){throw bad("Invalid UUID");}}private String str(Object v){return v==null?null:v.toString();}private LocalDate date(Object v){return v==null||v.toString().isBlank()?null:LocalDate.parse(v.toString());}private BigDecimal amount(Map<String,Object>b,String k){try{BigDecimal n=new BigDecimal(required(b,k));if(n.signum()<=0)throw bad(k+" must be positive");return n;}catch(NumberFormatException e){throw bad(k+" must be numeric");}}private String norm(Object v,String d){return v==null||v.toString().isBlank()?d:v.toString().trim().toUpperCase(Locale.ROOT);}private ApiException bad(String s){return new ApiException(HttpStatus.BAD_REQUEST,"WAREHOUSE_INVALID",s);}private ApiException conflict(String s){return new ApiException(HttpStatus.CONFLICT,"WAREHOUSE_CONFLICT",s);}private ApiException missing(String s){return new ApiException(HttpStatus.NOT_FOUND,s,"Warehouse resource not found");}
}
